                parent_name=l1_category
            )

            # Store in tree
            for cluster_name, members in l2_clusters.items():
                self.tree['L1'][l1_category]['children'][cluster_name] = {
                    'members': members,
                    'children': {}
                }

    def _build_level_3(self):
        """Build level 3 with 3-20 subcategories per L2 parent."""
        for l1 in self.tree['L1']:
            for l2 in self.tree['L1'][l1]['children']:
                l1_members = self.tree['L1'][l1]['members']
                l2_members = self.tree['L1'][l1]['children'][l2]['members']

                # Collect L3 categories
                l3_candidates = defaultdict(int)

                for source, path in self.all_categories:
                    if len(path) >= 3:
                        if path[0] in l1_members and path[1] in l2_members:
                            l3_candidates[path[2]] += 1

                if not l3_candidates:
                    continue

                l3_list = list(l3_candidates.keys())
                l3_clusters = self._hierarchical_cluster(
                    l3_list,
                    target_min=3,
                    target_max=20,
                    similarity_threshold=0.20,
                    parent_name=l2
                )

                for cluster_name, members in l3_clusters.items():
                    self.tree['L1'][l1]['children'][l2]['children'][cluster_name] = {
                        'members': members,
                        'children': {}
                    }

    def _build_level_4(self):
        """Build level 4 with 3-20 subcategories per L3 parent."""
        for l1 in self.tree['L1']:
            for l2 in self.tree['L1'][l1]['children']:
                for l3 in self.tree['L1'][l1]['children'][l2]['children']:
                    l1_members = self.tree['L1'][l1]['members']
                    l2_members = self.tree['L1'][l1]['children'][l2]['members']
                    l3_members = self.tree['L1'][l1]['children'][l2]['children'][l3]['members']

                    l4_candidates = defaultdict(int)

                    for source, path in self.all_categories:
                        if len(path) >= 4:
                            if (path[0] in l1_members and
                                path[1] in l2_members and
                                path[2] in l3_members):
                                l4_candidates[path[3]] += 1

                    if not l4_candidates:
                        continue

                    l4_list = list(l4_candidates.keys())
                    l4_clusters = self._hierarchical_cluster(
                        l4_list,
                        target_min=3,
                        target_max=20,
                        similarity_threshold=0.15,
                        parent_name=l3
                    )

                    for cluster_name, members in l4_clusters.items():
                        self.tree['L1'][l1]['children'][l2]['children'][l3]['children'][cluster_name] = {
                            'members': members,
                            'children': {}
                        }

    def _build_level_5(self):
        """Build level 5 with 3-20 subcategories per L4 parent."""
        for l1 in self.tree['L1']:
            for l2 in self.tree['L1'][l1]['children']:
                for l3 in self.tree['L1'][l1]['children'][l2]['children']:
                    for l4 in self.tree['L1'][l1]['children'][l2]['children'][l3]['children']:
                        l1_members = self.tree['L1'][l1]['members']
                        l2_members = self.tree['L1'][l1]['children'][l2]['members']
                        l3_members = self.tree['L1'][l1]['children'][l2]['children'][l3]['members']
                        l4_members = self.tree['L1'][l1]['children'][l2]['children'][l3]['children'][l4]['members']

                        l5_candidates = defaultdict(int)

                        for source, path in self.all_categories:
                            if len(path) >= 5:
                                if (path[0] in l1_members and
                                    path[1] in l2_members and
                                    path[2] in l3_members and
                                    path[3] in l4_members):
                                    l5_candidates[path[4]] += 1

                        if not l5_candidates:
                            continue

                        l5_list = list(l5_candidates.keys())
                        l5_clusters = self._hierarchical_cluster(
                            l5_list,
                            target_min=3,
                            target_max=20,
                            similarity_threshold=0.10,
                            parent_name=l4
                        )

                        for cluster_name, members in l5_clusters.items():
                            self.tree['L1'][l1]['children'][l2]['children'][l3]['children'][l4]['children'][cluster_name] = {
                                'members': members,
                                'children': {}
                            }

    def _hierarchical_cluster(self, categories: List[str], target_min: int,
                             target_max: int, similarity_threshold: float,
                             parent_name: str = None) -> Dict[str, List[str]]:
        """Cluster categories into target range with similarity constraints."""
        if not categories:
            return {}

        freq = Counter(categories)
        sorted_cats = sorted(freq.items(), key=lambda x: (-x[1], x[0]))

        clusters = {}
        assigned = set()
        cluster_centers = []

        target = min(max(len(categories) // 8, target_min), target_max)

        # Select initial cluster centers
        for cat, count in sorted_cats:
            if len(cluster_centers) >= target:
                break

            # Avoid parent overlap
            if parent_name and has_parent_overlap(cat, parent_name):
                continue

            # Check sibling similarity
            too_similar = False
            for center in cluster_centers:
                overlap = calculate_word_overlap(cat, center)
                if overlap > 0.30:  # Ensure < 30% word overlap
                    too_similar = True
                    break

            if not too_similar:
                cluster_centers.append(cat)
                clusters[cat] = [cat]
                assigned.add(cat)

        # Ensure we have at least target_min clusters
        if len(cluster_centers) < target_min:
            for cat, count in sorted_cats:
                if cat in assigned:
                    continue
                if len(cluster_centers) >= target_min:
                    break

                if parent_name and has_parent_overlap(cat, parent_name):
                    continue

                cluster_centers.append(cat)
                clusters[cat] = [cat]
                assigned.add(cat)

        # Assign remaining categories
        for cat, count in sorted_cats:
            if cat in assigned:
                continue

            if parent_name and has_parent_overlap(cat, parent_name):
                continue

            # Find best cluster
            best_cluster = None
            best_similarity = 0

            for center in cluster_centers:
                similarity = calculate_word_overlap(cat, center)
                if similarity > best_similarity:
                    best_similarity = similarity
                    best_cluster = center

            if best_cluster and best_similarity >= similarity_threshold:
                clusters[best_cluster].append(cat)
                assigned.add(cat)
            else:
                # Create new cluster if under max
                if len(clusters) < target_max:
                    clusters[cat] = [cat]
                    cluster_centers.append(cat)
                    assigned.add(cat)
                else:
                    # Assign to smallest cluster
                    smallest = min(clusters.keys(), key=lambda c: len(clusters[c]))
                    clusters[smallest].append(cat)
                    assigned.add(cat)

        return clusters

    def _create_final_mappings(self):
        """Create final mappings from original paths to unified paths."""
        for source, path in self.all_categories:
            unified_path = []

            # Find L1 mapping
            for l1, data in self.tree['L1'].items():
                if path[0] in data['members']:
                    unified_path.append(l1)
                    break

            if not unified_path:
                unified_path.append(path[0])

            # Find L2 mapping
            if len(path) >= 2 and len(unified_path) >= 1:
                l1 = unified_path[0]
                if l1 in self.tree['L1']:
                    for l2, data in self.tree['L1'][l1]['children'].items():
                        if path[1] in data['members']:
                            unified_path.append(l2)
                            break

            # Find L3 mapping
            if len(path) >= 3 and len(unified_path) >= 2:
                l1, l2 = unified_path[0], unified_path[1]
                if l1 in self.tree['L1'] and l2 in self.tree['L1'][l1]['children']:
                    for l3, data in self.tree['L1'][l1]['children'][l2]['children'].items():
                        if path[2] in data['members']:
                            unified_path.append(l3)
                            break

            # Find L4 mapping
            if len(path) >= 4 and len(unified_path) >= 3:
                l1, l2, l3 = unified_path[0], unified_path[1], unified_path[2]
                if (l1 in self.tree['L1'] and
                    l2 in self.tree['L1'][l1]['children'] and
                    l3 in self.tree['L1'][l1]['children'][l2]['children']):
                    for l4, data in self.tree['L1'][l1]['children'][l2]['children'][l3]['children'].items():
                        if path[3] in data['members']:
                            unified_path.append(l4)
                            break

            # Find L5 mapping
            if len(path) >= 5 and len(unified_path) >= 4:
                l1, l2, l3, l4 = unified_path[:4]
                if (l1 in self.tree['L1'] and
                    l2 in self.tree['L1'][l1]['children'] and
                    l3 in self.tree['L1'][l1]['children'][l2]['children'] and
                    l4 in self.tree['L1'][l1]['children'][l2]['children'][l3]['children']):
                    for l5, data in self.tree['L1'][l1]['children'][l2]['children'][l3]['children'][l4]['children'].items():
                        if path[4] in data['members']:
                            unified_path.append(l5)
                            break

            # Store mapping
            key = (source, ' > '.join(path))
            self.unified_mapping[key] = unified_path

    def generate_outputs(self):
        """Generate the two required output CSV files."""
        # File 1: unified_taxonomy_full.csv
        full_data = []

        for source, path in self.all_categories:
            key = (source, ' > '.join(path))
            unified_path = self.unified_mapping.get(key, path)

            # Pad to 5 levels
            unified_5 = (unified_path + [''] * 5)[:5]

            row = {
                'source': source,
                'category_path': ' > '.join(path),
                'depth': len(path),
                'unified_level_1': unified_5[0],
                'unified_level_2': unified_5[1],
                'unified_level_3': unified_5[2],
                'unified_level_4': unified_5[3],
                'unified_level_5': unified_5[4],
            }
            full_data.append(row)

        df_full = pd.DataFrame(full_data)
        df_full.to_csv('/root/output/unified_taxonomy_full.csv', index=False)

        # File 2: unified_taxonomy_hierarchy.csv
        hierarchy_data = []

        def traverse(node, path, level):
            """Recursively traverse tree to collect all paths."""
            if level <= 5:
                # Add current path
                path_5 = (path + [''] * 5)[:5]
                hierarchy_data.append({
                    'unified_level_1': path_5[0],
                    'unified_level_2': path_5[1],
                    'unified_level_3': path_5[2],
                    'unified_level_4': path_5[3],
                    'unified_level_5': path_5[4],
                })

                # Traverse children
                if 'children' in node and node['children']:
                    for child_name, child_node in node['children'].items():
                        traverse(child_node, path + [child_name], level + 1)

        # Start traversal from L1
        for l1_name, l1_node in self.tree['L1'].items():
            traverse(l1_node, [l1_name], 1)

        df_hierarchy = pd.DataFrame(hierarchy_data)
        df_hierarchy = df_hierarchy.drop_duplicates()
        df_hierarchy.to_csv('/root/output/unified_taxonomy_hierarchy.csv', index=False)

        return df_full, df_hierarchy

